DELETE FROM kanji_map_reading WHERE EXISTS (SELECT 1 FROM kanji_map_node n WHERE n.kanji_character=kanji_map_reading.kanji_character AND n.is_active=TRUE);

DELETE FROM kanji_map_gloss WHERE EXISTS (SELECT 1 FROM kanji_map_node n WHERE n.kanji_character=kanji_map_gloss.kanji_character AND n.is_active=TRUE);

DELETE FROM kanji_map_radical_alias WHERE EXISTS (SELECT 1 FROM kanji_map_node n WHERE n.kanji_character=kanji_map_radical_alias.kanji_character AND n.is_active=TRUE);

DELETE FROM kanji_map_component WHERE EXISTS (SELECT 1 FROM kanji_map_node n WHERE n.kanji_character=kanji_map_component.kanji_character AND n.is_active=TRUE);

DELETE FROM kanji_map_stroke WHERE EXISTS (SELECT 1 FROM kanji_map_node n WHERE n.kanji_character=kanji_map_stroke.kanji_character AND n.is_active=TRUE);












































































































































































































































































































































































































































































































































